#include <stdatomic.h>
#include <stddef.h>
#include <stdint.h>

#define RB_SIZE 256                       /* power of two: the wrap is a mask */
#define RB_MASK (RB_SIZE - 1)

typedef struct {
    _Alignas(64) atomic_uint head;         /* producer-owned, padded to its own line */
    _Alignas(64) atomic_uint tail;         /* consumer-owned, on a different line  */
    uint32_t buf[RB_SIZE];                 /* the fixed array: no allocation */
    atomic_uint overrun;                   /* drops detected, so loss is observable */
} ring_t;

static inline void rb_push(ring_t *r, uint32_t v) {
    uint32_t h = atomic_load_explicit(&r->head, memory_order_relaxed);
    if (h == atomic_load_explicit(&r->tail, memory_order_acquire)) {
        /* full: capacity policy - overwrite the oldest, and count the loss */
        atomic_fetch_add_explicit(&r->overrun, 1, memory_order_relaxed);
        atomic_store_explicit(&r->tail, (h + 1) & RB_MASK, memory_order_relaxed);
    }
    r->buf[h] = v;                         /* item first ... */
    atomic_store_explicit(&r->head, (h + 1) & RB_MASK, memory_order_release); /* ... then publish */
}

static inline int rb_pop(ring_t *r, uint32_t *out) {
    uint32_t t = atomic_load_explicit(&r->tail, memory_order_relaxed);
    if (t == atomic_load_explicit(&r->head, memory_order_acquire)) return 0;  /* empty */
    *out = r->buf[t];                      /* acquire on head: the item IS written */
    atomic_store_explicit(&r->tail, (t + 1) & RB_MASK, memory_order_relaxed);
    return 1;
}
/* NOTE: `volatile` is NOT a substitute: it gives visibility, not the ordering
   between the item write and the head publish that the ring's correctness needs. */
